const F=(it,en,aura,hair,eye,x)=>({n:T(it,en),aura,hair:hair||null,eye:eye||null,x:x||null});
function cfgForForm(C,idx){
  const cfg=Object.assign({},C.cfg),e=idx>=0?LINES[C.line||'saiyan'][idx]:null;
  if(e){
    if(e.hair&&!C.keepHair&&!['bald','antenna','horns'].includes(C.cfg.hs))cfg.hair=e.hair;
    if(e.eye)cfg.eye=e.eye;
    if(e.x)Object.assign(cfg,e.x);
  }
  return cfg;
}
